    await skills.wait(bot, 300);

    const hutSpots = [
        { x: -1503, y: 63, z: 547 },
        { x: -1504, y: 63, z: 547 },
        { x: -1503, y: 63, z: 546 },
        { x: -1504, y: 63, z: 546 },
    ];

