// DESCRIPTION: Walk to the nearest block of blockName within range and activate it; returns the block or null.
async function goToBlockAndInteract(bot, blockName, range = 32) {
    const ok = await skills.goToNearestBlock(bot, blockName, 2, range);
    const block = world.getNearestBlock(bot, blockName, 4);
    if (!ok || !block) return null;
    await bot.lookAt(block.position.offset(0.5, 0.5, 0.5));
    if (!blockName.includes('chest') && !blockName.includes('furnace')) await bot.activateBlock(block);
    return block;
}

// DESCRIPTION: Craft itemName until the inventory holds at least target, walking to the nearest crafting_table if one is needed; returns true on success.
async function craftItem(bot, itemName, target = 1) {
    const have = () => world.getInventoryCounts(bot)[itemName] || 0;
    if (!world.getNearestBlock(bot, 'crafting_table', 6) && !world.getInventoryCounts(bot)['crafting_table'])
        await skills.goToNearestBlock(bot, 'crafting_table', 3, 48);
    for (let i = 0; i < target && have() < target; i++) {
        if (bot.interrupt_code) return false;
        if (!(await skills.craftRecipe(bot, itemName, 1))) break;
    }
    return have() >= target;
}

// DESCRIPTION: Walk to the nearest furnace (within 48 blocks) if any, then smelt count of inputName using coal or other fuel; returns true on success.
async function smeltItems(bot, inputName, count = 1) {
    if (!world.getNearestBlock(bot, 'furnace', 6) && world.getNearestBlock(bot, 'furnace', 48))
        await skills.goToNearestBlock(bot, 'furnace', 2, 48);
