// DESCRIPTION: Place four cobblestone blocks at (-1506,63,z) for z=544..547 and verify exactly four were used.
async function placeHutSouthCobblePath(bot) {
    const countCobble = () => {
        const stack = bot.inventory.items().find((i) => i.name === 'cobblestone');
        return stack ? stack.count : 0;
    };

    const pathX = -1506;
    const pathY = 63;
    const zs = [544, 545, 546, 547];

    if (bot.interrupt_code) return;
    if (countCobble() < 4) {
        await bot.chat(`Need 4 cobblestone; have ${countCobble()}.`);
        return;
    }

    const cobbleBefore = countCobble();
    const p = world.getPosition(bot);
    if (Math.abs(p.x - pathX) > 2 || Math.abs(p.y - pathY) > 2 || Math.abs(p.z - zs[0]) > 4) {
        if (bot.interrupt_code) return;
        await skills.goToPosition(bot, pathX + 1, pathY, zs[0]);
        if (bot.interrupt_code) return;
        await skills.wait(bot, 500);
    }

    for (let i = 0; i < zs.length; i++) {
        if (bot.interrupt_code) return;
        const z = zs[i];
        const target = bot.blockAt(new Vec3(pathX, pathY, z));
        if (target && target.name === 'cobblestone') continue;
        if (target && target.name !== 'air') {
            await bot.chat(`Blocked at z=${z}: ${target.name}`);
            continue;
        }

        const floor = bot.blockAt(new Vec3(pathX, pathY - 1, z));
        if (!floor || floor.name === 'air' || floor.name === 'water') {
            await bot.chat(`No floor at z=${z}; skip.`);
            continue;
        }

        await skills.goToPosition(bot, pathX + 1, pathY, z);
        if (bot.interrupt_code) return;
        await skills.wait(bot, 400);

        let placed = await skills.placeBlock(bot, 'cobblestone', pathX, pathY, z, 'west');
        if (bot.interrupt_code) return;
        if (!placed) placed = await skills.placeBlock(bot, 'cobblestone', pathX, pathY, z, 'top');
        if (bot.interrupt_code) return;
        if (!placed) {
            await skills.goToPosition(bot, pathX, pathY, z + 1);
            if (bot.interrupt_code) return;
            placed = await skills.placeBlock(bot, 'cobblestone', pathX, pathY, z, 'north');
        }
        if (bot.interrupt_code) return;
        if (!placed) await bot.chat(`placeBlock FAILED z=${z}`);
        await skills.wait(bot, 200);
    }

    if (bot.interrupt_code) return;
    let allCobble = true;
    for (let j = 0; j < zs.length; j++) {
        const b = bot.blockAt(new Vec3(pathX, pathY, zs[j]));
        if (!b || b.name !== 'cobblestone') allCobble = false;
    }
    const used = cobbleBefore - countCobble();
    await bot.chat(
        allCobble && used === 4
            ? 'Path OK: 4 cobble at y=63 x=-1506 z=544..547.'
            : `Path verify FAIL allCobble=${allCobble} cobble_used=${used}/4.`
    );
}

// DESCRIPTION: Return true if x,z is within maxRange (default 48) of the bot and far (>200) from the players' village at -800,500.
function isSafeTarget(bot, x, z, maxRange = 48) {
    const p = bot.entity.position;
    if (Math.hypot(x - p.x, z - p.z) > maxRange) return false;
    return Math.hypot(x - (-800), z - 500) > 200;
}

// DESCRIPTION: Equip the best tool of toolType (pickaxe, axe, sword, shovel, hoe) in the inventory; returns the item name or null.
async function equipBestTool(bot, toolType = 'pickaxe') {
    const tiers = ['netherite', 'diamond', 'iron', 'stone', 'golden', 'wooden'];
    const inv = world.getInventoryCounts(bot);
    for (const t of tiers) {
        const name = `${t}_${toolType}`;
        if (inv[name]) { await skills.equip(bot, name); return name; }
    }
    return null;
}

// DESCRIPTION: Equip the best toolType, crafting one (iron > stone > wooden) if none is held; returns the equipped name or null.
async function equipToolOrCraft(bot, toolType = 'pickaxe') {
    let got = await equipBestTool(bot, toolType);
    if (got) return got;
    const inv = world.getInventoryCounts(bot);
    const planks = Object.keys(inv).filter(k => k.endsWith('_planks')).reduce((a, k) => a + inv[k], 0);
    const mat = (inv.iron_ingot || 0) >= 3 ? 'iron' : (inv.cobblestone || 0) >= 3 ? 'stone' : planks >= 3 || Object.keys(inv).some(k => k.endsWith('_log')) ? 'wooden' : null;
    if (!mat || bot.interrupt_code) return null;
    if ((inv.stick || 0) < 2) await craftSticks(bot, 4);
    if (bot.interrupt_code) return null;
    await craftItem(bot, `${mat}_${toolType}`, 1);
    return await equipBestTool(bot, toolType);
}

// DESCRIPTION: Wear the best helmet, chestplate, leggings and boots in the inventory; returns how many pieces were equipped.
async function equipBestArmor(bot) {
    const tiers = ['netherite', 'diamond', 'iron', 'chainmail', 'golden', 'leather'];
    const inv = world.getInventoryCounts(bot);
    let n = 0;
    for (const slot of ['helmet', 'chestplate', 'leggings', 'boots']) {
        if (bot.interrupt_code) return n;
        const t = tiers.find(t => inv[`${t}_${slot}`]);
        if (t && await skills.equip(bot, `${t}_${slot}`)) n++;
    }
    return n;
}

// DESCRIPTION: Craft planks from whatever logs are in the inventory until there are at least target planks; returns true on success.
async function craftPlanks(bot, target = 4) {
    const planks = () => Object.entries(world.getInventoryCounts(bot)).filter(([k]) => k.endsWith('_planks')).reduce((a, [, v]) => a + v, 0);
    for (let i = 0; i < 16 && planks() < target; i++) {
        if (bot.interrupt_code) return false;
        const log = Object.keys(world.getInventoryCounts(bot)).find(k => k.endsWith('_log') && !k.startsWith('stripped'));
        if (!log) return false;
        if (!(await skills.craftRecipe(bot, log.replace('_log', '_planks'), 1))) return false;
    }
    return planks() >= target;
}

// DESCRIPTION: Craft sticks (making planks from logs if needed) until the inventory has target sticks; returns true on success.
async function craftSticks(bot, target = 4) {
    const have = () => world.getInventoryCounts(bot).stick || 0;
    for (let i = 0; i < 8 && have() < target; i++) {
        if (bot.interrupt_code) return false;
        await craftPlanks(bot, 2);
        if (!(await skills.craftRecipe(bot, 'stick', 1))) return false;
    }
    return have() >= target;
}

// DESCRIPTION: Chop count logs of the nearest tree type (or logType if given) and pick up drops; returns logs gained.
async function collectLogs(bot, count = 4, logType = null) {
    let type = logType;
    if (!type) {
        const b = world.getNearestBlocksWhere(bot, b => b.name.endsWith('_log') && !b.name.startsWith('stripped'), 32, 1)[0];
        type = b ? b.name : 'birch_log';
    }
    await equipBestTool(bot, 'axe');
    if (bot.interrupt_code) return 0;
    return await mineBlocks(bot, type, count);
}

// DESCRIPTION: Make sure a crafting_table is within 16 blocks, crafting and placing one if not; returns true if one is available.
async function ensureCraftingTable(bot) {
    if (world.getNearestBlock(bot, 'crafting_table', 16)) return true;
    if (!world.getInventoryCounts(bot).crafting_table) {
        if (!(await craftPlanks(bot, 4)) || bot.interrupt_code) return false;
        if (!(await skills.craftRecipe(bot, 'crafting_table', 1))) return false;
    }
    if (bot.interrupt_code) return false;
    const pos = world.getNearestFreeSpace(bot, 1, 6);
    if (!pos) return false;
    await skills.placeBlock(bot, 'crafting_table', pos.x, pos.y, pos.z);
    return !!world.getNearestBlock(bot, 'crafting_table', 16);
}

// DESCRIPTION: Make sure a furnace is within 16 blocks, mining cobblestone, crafting and placing one if not; returns true if one is available.
async function ensureFurnace(bot) {
    if (world.getNearestBlock(bot, 'furnace', 16)) return true;
    if (!world.getInventoryCounts(bot).furnace) {
        if ((world.getInventoryCounts(bot).cobblestone || 0) < 8) await mineOre(bot, 'stone', 8 - (world.getInventoryCounts(bot).cobblestone || 0));
        if (bot.interrupt_code || (world.getInventoryCounts(bot).cobblestone || 0) < 8) return false;
