// DESCRIPTION: Mine count of an ore or stone (coal_ore, iron_ore, diamond_ore, stone, deepslate variants...), first equipping or crafting a pickaxe good enough for it; returns items gained.
async function mineOre(bot, oreName, count = 1) {
    const need = { stone: 'wooden', cobblestone: 'wooden', coal_ore: 'wooden', copper_ore: 'stone', iron_ore: 'stone', lapis_ore: 'stone', gold_ore: 'iron', redstone_ore: 'iron', diamond_ore: 'iron', emerald_ore: 'iron' };
    const rank = { wooden: 0, golden: 0, stone: 1, iron: 2, diamond: 3, netherite: 4 };
    const base = oreName.replace('deepslate_', '');
    const req = need[base] || 'wooden';
    let held = await equipToolOrCraft(bot, 'pickaxe');
    if (bot.interrupt_code) return 0;
    const tier = held ? held.split('_')[0] : null;
    if (!tier || rank[tier] < rank[req]) { log(bot, `mineOre: need a ${req}_pickaxe or better for ${oreName}`); return 0; }
    return await mineBlocks(bot, oreName === 'cobblestone' ? 'stone' : oreName, count);
}

// DESCRIPTION: Collect count of a surface block (dirt, sand, gravel, clay, sugar_cane, cactus, bamboo, pumpkin, melon, flowers) with the right tool; returns items gained.
async function collectSurface(bot, blockName, count = 1) {
    const tool = /sand|dirt|gravel|clay|grass|snow/.test(blockName) ? 'shovel' : /pumpkin|melon|bamboo/.test(blockName) ? 'axe' : null;
    if (tool) await equipBestTool(bot, tool);
    if (bot.interrupt_code) return 0;
    return await mineBlocks(bot, blockName, count);
}

// DESCRIPTION: Smelt count of inputName (raw_iron, raw_copper, raw_gold, sand, cactus, cobblestone...), placing a furnace and finding fuel if needed; returns true on success.
async function smeltWithFuel(bot, inputName, count = 1) {
    if ((world.getInventoryCounts(bot)[inputName] || 0) < count) { log(bot, `smeltWithFuel: only have ${world.getInventoryCounts(bot)[inputName] || 0} ${inputName}`); return false; }
    if (!world.getNearestBlock(bot, 'furnace', 48) && !(await ensureFurnace(bot))) return false;
    if (bot.interrupt_code) return false;
    const inv = world.getInventoryCounts(bot);
    const hasFuel = inv.coal || inv.charcoal || Object.keys(inv).some(k => k.endsWith('_planks') || k.endsWith('_log'));
    if (!hasFuel) { await mineOre(bot, 'coal_ore', 2); if (bot.interrupt_code) return false; }
    return await smeltItems(bot, inputName, count);
}

// DESCRIPTION: Cook up to count raw meat/fish from the inventory in a furnace; returns true if anything was cooked.
async function cookFood(bot, count = 1) {
    const raw = ['beef', 'porkchop', 'mutton', 'chicken', 'rabbit', 'cod', 'salmon', 'potato'];
    const inv = world.getInventoryCounts(bot);
    const item = raw.find(r => inv[r]);
    if (!item) return false;
    return await smeltWithFuel(bot, item, Math.min(count, inv[item]));
}

// DESCRIPTION: Kill count mobs of mobType within 48 blocks (never near the players' village), equipping the best sword first, then pick up drops; returns how many were killed.
async function killMob(bot, mobType, count = 1) {
    let killed = 0;
    for (let i = 0; i < count * 2 && killed < count; i++) {
        if (bot.interrupt_code) return killed;
        const e = bot.nearestEntity(en => en.name === mobType && en.position.distanceTo(bot.entity.position) <= 48);
        if (!e || !(await isSafeTarget(bot, e.position.x, e.position.z, 48))) break;
        if (!(await equipBestTool(bot, 'sword'))) await equipBestTool(bot, 'axe');
        if (bot.interrupt_code) return killed;
        if (await skills.attackEntity(bot, e, true)) killed++;
        await skills.pickupNearbyItems(bot);
    }
    return killed;
}

// DESCRIPTION: Fight hostile mobs within range (max 48) until none are left or 10 fights; returns how many were killed.
async function killMonsters(bot, range = 16) {
    range = Math.min(range, 48);
    const hostile = ['zombie', 'skeleton', 'spider', 'creeper', 'husk', 'drowned', 'witch', 'slime', 'cave_spider', 'enderman', 'pillager', 'zombie_villager', 'stray'];
    // fix5: 'A Breach Happened' figures (mannequins, profile "fd", 60 HP) are hostile but too strong; flee instead of fighting
    const isFigure = en => en !== bot.entity && (en.name === 'mannequin' || (en.type === 'player' && (en.username === 'fd' || !en.username)) || /Black Figure|Red Figure|The Man\b/i.test(JSON.stringify(en.metadata ?? '') + (en.customName ?? '')));
    const fig = bot.nearestEntity(en => isFigure(en) && en.position.distanceTo(bot.entity.position) <= Math.max(range, 24));
    if (fig) { console.log(`[killMonsters] datapack hostile ${fig.name} ${fig.position.distanceTo(bot.entity.position).toFixed(1)} blocks away; fleeing instead of fighting`); await skills.avoidEnemies(bot, 24); return 0; }
    let n = 0;
    for (let i = 0; i < 10; i++) {
        if (bot.interrupt_code) return n;
        const e = bot.nearestEntity(en => hostile.includes(en.name) && en.position.distanceTo(bot.entity.position) <= range);
        if (!e) break;
        if (!(await equipBestTool(bot, 'sword'))) await equipBestTool(bot, 'axe');
        if (await skills.attackEntity(bot, e, true)) n++;
    }
    return n;
}

// DESCRIPTION: Get at least n cooked food: hunt cows/pigs/sheep/chickens within 48 blocks, cook the meat, then eat if hungry; returns true if the inventory has n cooked food.
async function getFood(bot, n = 2) {
    const cooked = () => Object.entries(world.getInventoryCounts(bot)).filter(([k]) => k.startsWith('cooked_') || k === 'bread' || k === 'baked_potato').reduce((a, [, v]) => a + v, 0);
    for (const mob of ['cow', 'pig', 'sheep', 'chicken']) {
        if (bot.interrupt_code || cooked() >= n) break;
        await killMob(bot, mob, n - cooked());
    }
    if (bot.interrupt_code) return false;
    if (cooked() < n) await cookFood(bot, n);
    if (bot.food < 14) await eatFood(bot);
    return cooked() >= n;
}

// DESCRIPTION: Craft torches until the inventory has target, making sticks and mining coal if needed; returns true on success.
async function craftTorches(bot, target = 4) {
    const have = () => world.getInventoryCounts(bot).torch || 0;
    for (let i = 0; i < 6 && have() < target; i++) {
        if (bot.interrupt_code) return false;
        const inv = world.getInventoryCounts(bot);
        if (!inv.coal && !inv.charcoal) { await mineOre(bot, 'coal_ore', 1); if (bot.interrupt_code) return false; }
        if (!(world.getInventoryCounts(bot).stick)) await craftSticks(bot, 1);
        if (!(await skills.craftRecipe(bot, 'torch', 1))) return false;
    }
    return have() >= target;
}

