// DESCRIPTION: Harvest up to count fully grown crops (wheat, carrots, potatoes, beetroots) within 32 blocks and pick up drops; returns how many were harvested.
async function harvestCrop(bot, crop = 'wheat', count = 4) {
    const maxAge = crop === 'beetroots' ? 3 : 7;
    let n = 0;
    for (let i = 0; i < count; i++) {
        if (bot.interrupt_code) return n;
        const b = world.getNearestBlocksWhere(bot, bl => bl.name === crop && bl.getProperties?.().age === maxAge, 32, 1)[0];
        if (!b) break;
        await skills.breakBlockAt(bot, b.position.x, b.position.y, b.position.z);
        n++;
    }
    await skills.pickupNearbyItems(bot);
    return n;
}

// DESCRIPTION: Till and plant up to count seeds (wheat_seeds, carrot, potato, beetroot_seeds, melon_seeds, pumpkin_seeds) on dirt/grass near water within 16 blocks; returns how many were planted.
async function plantSeeds(bot, seed = 'wheat_seeds', count = 4) {
    if (!(await equipToolOrCraft(bot, 'hoe'))) return 0;
    let n = 0;
    for (let i = 0; i < count * 2 && n < count; i++) {
        if (bot.interrupt_code || !(world.getInventoryCounts(bot)[seed])) break;
        const soil = world.getNearestBlocksWhere(bot, bl => {
            if (!['dirt', 'grass_block', 'farmland'].includes(bl.name)) return false;
            const above = bot.blockAt(bl.position.offset(0, 1, 0));
            return above && above.name === 'air';
        }, 16, 1)[0];
        if (!soil) break;
        if (await skills.tillAndSow(bot, soil.position.x, soil.position.y, soil.position.z, seed)) n++;
        else break;
    }
    return n;
}

// DESCRIPTION: Feed two nearby animals of a type (cow/sheep: wheat, pig: carrot, chicken: wheat_seeds) within 16 blocks so they breed; returns true if two were fed.
async function breedAnimal(bot, animal = 'cow') {
    const food = { cow: 'wheat', sheep: 'wheat', pig: 'carrot', chicken: 'wheat_seeds', rabbit: 'carrot' }[animal];
    if (!food || (world.getInventoryCounts(bot)[food] || 0) < 2) return false;
    const mobs = Object.values(bot.entities).filter(e => e.name === animal && e.position.distanceTo(bot.entity.position) <= 16).slice(0, 2);
    if (mobs.length < 2) return false;
    for (const m of mobs) {
